DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.finance_reconciliation_base_rows(uuid,date)'::regprocedure) INTO def;def:=replace(def,'public.finance_reconciliation_base_rows(', 'public.smart_alert_reconciliation_base(');def:=replace(def,'IF NOT public.user_has_tenant(auth.uid(),p_tenant) OR NOT (public.is_tenant_admin(p_tenant,auth.uid()) OR public.has_role(auth.uid(),''admin'')) THEN','IF auth.role() IS DISTINCT FROM ''service_role'' THEN');EXECUTE def;END $$;
REVOKE ALL ON FUNCTION public.smart_alert_reconciliation_base(uuid,date) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.smart_alert_reconciliation_base(uuid,date) TO service_role;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.finance_reconciliation_rows(uuid,date)'::regprocedure) INTO def;def:=replace(def,'public.finance_reconciliation_rows(', 'public.smart_alert_reconciliations(');def:=replace(def,'finance_reconciliation_base_rows(p_tenant,p_month)', 'smart_alert_reconciliation_base(p_tenant,p_month)');EXECUTE def;END $$;
REVOKE ALL ON FUNCTION public.smart_alert_reconciliations(uuid,date) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.smart_alert_reconciliations(uuid,date) TO service_role;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.smart_alert_edit_mute(uuid,uuid,jsonb)'::regprocedure) INTO def;def:=replace(def,'THEN ''sales'' ELSE ''finance'' END','THEN ''sales'' WHEN m.kind LIKE ''%bill%'' THEN ''expenses'' WHEN m.kind LIKE ''%bank%'' THEN ''bank'' WHEN m.kind LIKE ''%card%'' THEN ''payments'' WHEN m.kind=''supplier_price_rise'' THEN ''procurement'' ELSE ''finance'' END');EXECUTE def;END $$;